# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.5.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.5"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.5/berth-darwin-arm64.tar.gz"
      sha256 "487c99b202e4704ae7e9fea791edc21491bef894dc9c02b7a10ea9ef38542e4e"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.5/berth-darwin-amd64.tar.gz"
      sha256 "d9eb0eb05189b32e5ba8c142f46d08fd7ad2eb19c88597b6bcb0618dff24d91a"
    end

    # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones
    # come in berth's own archive.
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.5/berthd-darwin-arm64.tar.gz"
      sha256 "d604ed7af2dfa7900a0bd20273e34254424248c388146a7fb6e8771c588217be"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.5/berthd-darwin-amd64.tar.gz"
      sha256 "e174ae4f5a4d8ca1864d35789d524aecd1afefffc70f50eb96d3d99c8c93cfdc"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.5/berth-linux-arm64.tar.gz"
      sha256 "b390ebfe171fafe56e555bddb21e04baa3965736554bf0531e247bb623e86f85"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.5/berth-linux-amd64.tar.gz"
      sha256 "096a0234bf01f4837f4f1ac18168b869c43b9d30c9376e4615a29b5707decaed"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
